function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }

const CONFIG = {
  level1Url: 'https://httpbin.org/post',
  level2Url: 'https://httpbin.org/post',
  level3Url: 'https://httpbin.org/post',
  timeoutMs: 15000,
  // Dynamic policy thresholds
  policies: {
    autoApproveBelow: 500,
    level1Below: 5000,
    level2Below: 25000,
    // above level2Below → requires Level 3
    highRiskDepartments: ['legal', 'finance', 'security'],
    highRiskTypes: ['vendor_contract', 'data_access', 'production_change']
  },
  allowSimulation: true
};

const hook = ref('Webhook - Approval Request');
const body = (hook.body && typeof hook.body === 'object') ? hook.body : {};
const errors = [];

const requestId = String(body.requestId || body.id || ('APR-' + Date.now())).trim();
const type = String(body.type || body.requestType || 'general').toLowerCase();
const amount = Number(body.amount || body.value || 0);
const department = String(body.department || 'general').toLowerCase();
const requester = String(body.requester || body.requesterEmail || '').trim();
const description = String(body.description || '').slice(0, 500);
const urgency = String(body.urgency || 'normal').toLowerCase();

if (!requester) errors.push('requester is required');
if (!Number.isFinite(amount) || amount < 0) errors.push('amount must be a non-negative number');

const valid = errors.length === 0;

let level1Url = CONFIG.level1Url;
const sim = Number(body.simulateStatus);
if (CONFIG.allowSimulation && Number.isInteger(sim) && sim >= 200 && sim <= 599) {
  level1Url = 'https://httpbin.org/status/' + sim;
}

return [{
  json: {
    valid,
    errors,
    config: CONFIG,
    request: {
      requestId,
      type,
      amount,
      department,
      requester,
      description,
      urgency
    },
    urls: {
      level1: level1Url,
      level2: CONFIG.level2Url,
      level3: CONFIG.level3Url
    }
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Validate & Load Policies');
const p = ctx.config.policies;
const r = ctx.request;

let riskScore = 10;
if (r.amount >= 10000) riskScore += 30;
else if (r.amount >= 2000) riskScore += 15;
if (p.highRiskDepartments.includes(r.department)) riskScore += 25;
if (p.highRiskTypes.includes(r.type)) riskScore += 20;
if (r.urgency === 'critical') riskScore += 15;
riskScore = Math.min(riskScore, 100);

let requiredLevels = [];
let autoApproved = false;

if (r.amount < p.autoApproveBelow && riskScore < 40) {
  autoApproved = true;
  requiredLevels = [];
} else {
  requiredLevels.push(1);
  if (r.amount >= p.level1Below || riskScore >= 50) requiredLevels.push(2);
  if (r.amount >= p.level2Below || riskScore >= 75) requiredLevels.push(3);
}

return [{
  json: {
    requestId: r.requestId,
    config: ctx.config,
    request: r,
    urls: ctx.urls,
    evaluation: {
      riskScore,
      requiredLevels,
      autoApproved,
      maxLevel: requiredLevels.length ? Math.max(...requiredLevels) : 0
    },
    decisions: {},
    currentLevel: requiredLevels.length ? requiredLevels[0] : 0
  }
}];

