const ctx = ref('Code - Evaluate Policies');
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;

const needsL1 = (ctx.evaluation.requiredLevels || []).includes(1);
const approved = !needsL1 || (status >= 200 && status < 300);

const decisions = {
  ...ctx.decisions,
  level1: {
    required: needsL1,
    approved,
    status,
    decidedAt: new Date().toISOString()
  }
};

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    request: ctx.request,
    urls: ctx.urls,
    evaluation: ctx.evaluation,
    decisions,
    continueToL2: approved && (ctx.evaluation.requiredLevels || []).includes(2)
  }
}];

