function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Process Level 3');
const d = ctx.decisions || {};
const eval_ = ctx.evaluation || {};

let finalStatus = 'approved';
const rejectedLevels = [];

if (eval_.autoApproved) {
  finalStatus = 'auto_approved';
} else {
  for (const lvl of [1, 2, 3]) {
    const key = 'level' + lvl;
    if (d[key] && d[key].required && !d[key].approved) {
      finalStatus = 'rejected';
      rejectedLevels.push(lvl);
    }
  }
}

return [{
  json: {
    requestId: ctx.requestId,
    request: ctx.request,
    evaluation: eval_,
    decisions: d,
    final: {
      status: finalStatus,
      rejectedLevels,
      decidedAt: new Date().toISOString()
    }
  }
}];

