const ctx = ref('Code - Build Final Decision');

const httpStatus = ctx.final.status === 'rejected' ? 403 : 200;

const body = {
  status: ctx.final.status,
  requestId: ctx.requestId,
  request: ctx.request,
  evaluation: {
    riskScore: ctx.evaluation.riskScore,
    requiredLevels: ctx.evaluation.requiredLevels,
    autoApproved: ctx.evaluation.autoApproved
  },
  decisions: ctx.decisions,
  final: ctx.final
};

return [{
  json: {
    httpStatus,
    body,
    requestId: ctx.requestId
  }
}];
